cat > /tmp/validate_utk.py <<'PY'
import subprocess, time, sys, urllib.request, os
os.chdir("/home/lucas/projects/master-degree/autark-experiments/trials/app1-subway-accessibility/t4/utk/output")
srv = subprocess.Popen(["utk","start","--data","./data"],
                       stdout=open("srv.out","w"), stderr=subprocess.STDOUT)
def probe(path):
    try:
        r = urllib.request.urlopen("http://localhost:5001"+path, timeout=10)
        return r.status, len(r.read())
    except Exception as e:
        return "ERR", repr(e)[:120]
try:
    for i in range(20):
        time.sleep(1)
        if srv.poll() is not None:
            print("SERVER EXITED early rc=", srv.returncode); break
        st,_ = probe("/")
        if st == 200:
            print("server up after", i+1, "s"); break
    for p in ["/","/files/grammar.json","/files/buildings.json","/files/subwayCount.json","/files/water.json"]:
        print(f"{p:32} -> {probe(p)}")
    html = urllib.request.urlopen("http://localhost:5001/", timeout=10).read().decode("utf-8","replace")
    print("--- root html head ---")
    print(html[:300])
finally:
    srv.terminate()
    try: srv.wait(timeout=5)
    except Exception: srv.kill()
print("=== srv.out tail ===")
print(open("srv.out").read()[:1500])
PY
python3 /tmp/validate_utk.py
